// Compute Indicators v2 MULTI — BTC + ETH + SOL + BNB.
// Merge-append delivers candles as SEPARATE ITEMS. Each kline item is an array.
// Tagging: HTTP nodes now wrap candles as {symbol, candles:[...]}? No — n8n HTTP returns
// raw array items. To tag per-symbol we rely on ORDER: Merge appends input0..input4 in order,
// but klines of 4 symbols interleave. ROBUST FIX: separate HTTP nodes per symbol, each into
// its own Merge input is NOT possible (merge has 5 inputs, klines need 4).
// CHOSEN DESIGN: ONE HTTP node per symbol pair? Simplest reliable: keep Merge for
// ticker/funding/fng/cg (unchanged), and fetch the 4 kline sets with FOUR HTTP nodes
// chained Compute-side via $() reads. n8n $() can read other nodes' outputs:
//   $('Fetch ETH Klins').all() etc. This avoids merge-order fragility entirely.
function ind(klines){
  function sma(a,n){ if(!a || a.length<n) return null; let s=0; for(let i=a.length-n;i<a.length;i++) s+=a[i]; return s/n; }
  function ema(a,n){ if(!a || !a.length) return null; const k=2/(n+1); let e=a[0]; for(let i=1;i<a.length;i++) e=a[i]*k+e*(1-k); return e; }
  function rsi(cl,n){ if(!cl || cl.length<n+1) return null; let g=0,l=0; for(let i=cl.length-n;i<cl.length;i++){ const c=cl[i]-cl[i-1]; if(c>0) g+=c; else l-=c; } if(l===0) return 100; return 100-100/(1+(g/n)/(l/n)); }
  function atr(h,l,c,n){ if(!c || c.length<n+1) return null; const trs=[]; for(let i=c.length-n;i<c.length;i++){ trs.push(Math.max(h[i]-l[i], Math.abs(h[i]-c[i-1]), Math.abs(l[i]-c[i-1]))); } let s=0; for(const v of trs) s+=v; return s/trs.length; }
  function stoch(cl,hi,lo,kp,kd){ if(!cl || cl.length<kp+kd) return null; const ks=[]; for(let i=kp-1;i<cl.length;i++){ const hh=Math.max.apply(null,hi.slice(i-kp+1,i+1)); const ll=Math.min.apply(null,lo.slice(i-kp+1,i+1)); ks.push(hh===ll?50:(cl[i]-ll)/(hh-ll)*100); } const k=ks[ks.length-1]; const d=(ks[ks.length-1]+ks[ks.length-2]+ks[ks.length-3])/3; return {k:k, d:d}; }
  function adx(h,l,c,n){ if(!c || c.length < n*2+2) return null; let plus=0,minus=0,tr=0;
 for(let i=c.length-n*2+1;i<c.length;i++){ const up=h[i]-h[i-1], dn=l[i-1]-l[i]; let x=Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1])); tr+=x; plus+= (up>dn&&up>0)?up:0; minus+= (dn>up&&dn>0)?dn:0; }
 const di_p=tr>0?100*plus/tr:0, di_m=tr>0?100*minus/tr:0; const sum=di_p+di_m; return sum>0?Math.round(100*Math.abs(di_p-di_m)/sum):0; }
function macd(a){ if(!a || a.length<35) return null; function e(v,n){ const k=2/(n+1); let x=v[0]; for(let i=1;i<v.length;i++) x=v[i]*k+x*(1-k); return x; } const line=e(a.slice(-60),12)-e(a.slice(-60),26); return {line:line, hist_dir:'see-1h-trigger'}; }
  // normalize: array of candle-arrays OR array of items
  let K = klines;
  if(!Array.isArray(K)) return { error: 'not-array', closes: [] };
  if(K.length && !Array.isArray(K[0]) && K[0].json) K = K.map(function(i){ return i.json; });
  K = K.filter(function(x){ return Array.isArray(x); });
  if(!K.length) return { error: 'no-candles', closes: [] };
  K.sort(function(a,b){ return a[0]-b[0]; });
  const cl=K.map(function(r){ return parseFloat(r[4]); });
  const hi=K.map(function(r){ return parseFloat(r[2]); });
  const lo=K.map(function(r){ return parseFloat(r[3]); });
  const vo=K.map(function(r){ return parseFloat(r[5]); });
  const o={ closes: cl.slice(-5), sma20: sma(cl,20), sma50: sma(cl,50), sma200: cl.length>=200?sma(cl,200):null,
    ema12: ema(cl,12), ema26: ema(cl,26), rsi14: rsi(cl,14), atr14: atr(hi,lo,cl,14), stoch: stoch(cl,hi,lo,14,3), macd: macd(cl), adx14: adx(hi,lo,cl,14),
    high20: null, low20: null, relvol: null, chg7: null, chg30: null, bb: null, atr_pct: null, count: cl.length };
  if(o.atr14 && cl.length) o.atr_pct = o.atr14/cl[cl.length-1]*100;
  if(cl.length>=20){ const basis=sma(cl,20); let sd=0; const w=cl.slice(-20); for(const v of w) sd+=(v-basis)*(v-basis); sd=Math.sqrt(sd/20); o.bb={mid:basis, upper:basis+2*sd, lower:basis-2*sd, pos: cl[cl.length-1]>basis+2*sd?'above-upper':(cl[cl.length-1]<basis-2*sd?'below-lower':(cl[cl.length-1]>basis?'upper-half':'lower-half'))}; }
  if(hi.length>=20){ o.high20=Math.max.apply(null,hi.slice(-20)); o.low20=Math.min.apply(null,lo.slice(-20)); }
  if(vo.length>=21){ let s=0; for(let i=vo.length-21;i<vo.length-1;i++) s+=vo[i]; const avg=s/20; o.relvol=avg>0?vo[vo.length-1]/avg:null; }
  if(cl.length>=8) o.chg7=(cl[cl.length-1]/cl[cl.length-8]-1)*100;
  if(cl.length>=31) o.chg30=(cl[cl.length-1]/cl[cl.length-31]-1)*100;
  o.computed_at = new Date().toISOString();
  return o;
}
function grab(name){
  try {
    const items = $(name).all().map(function(i){ return i.json; });
    // HTTP klines node: items are candle arrays (or single array)
    if(items.length === 1 && Array.isArray(items[0]) && items[0].length && Array.isArray(items[0][0])) return items[0];
    return items;
  } catch(e){ return { error: String(e).slice(0,120) }; }
}
// merge passthrough data (ticker/funding/fng/cg) from $input as before
const items = $input.all().map(function(i){ return i.json; });
let ticker=[], funding=null, fng=null, cg=null;
for(const d of items){
  if(Array.isArray(d)) continue; // klines no longer come via merge
  if(d && d.symbol && d.lastPrice){ ticker.push(d); continue; }
  if(d && d.markPrice && d.lastFundingRate && !funding){ funding=d; continue; }
  if(d && d.data && d.data.market_cap_percentage){ cg=d; continue; }
  if(d && ((d.data && Array.isArray(d.data)) || d.name==='Fear and Greed Index')){ fng=d; continue; }
}
const symbols = ['BTCUSDT','ETHUSDT','SOLUSDT','BNBUSDT'];
const nodeMap = { BTCUSDT: 'Fetch 4H Klines Batch', ETHUSDT: 'Fetch ETH Klines', SOLUSDT: 'Fetch SOL Klines', BNBUSDT: 'Fetch BNB Klines' };
const feats = {};
for(const s of symbols){ feats[s] = ind(grab(nodeMap[s])); }
// funding per symbol
function grabFund(sym){
  try {
    const j = $('Fetch Funding ' + sym.replace('USDT','')).first().json;
    return j;
  } catch(e){ return null; }
}
const funds = { BTCUSDT: funding };
for(const s of ['ETHUSDT','SOLUSDT','BNBUSDT']){ const f = grabFund(s); if(f) funds[s] = f; }
let fngNow=null, fng7=[];
try{ const src=fng.data||fng; const arr=src.data||src; if(Array.isArray(arr)){ fngNow=parseFloat(arr[0].value); fng7=arr.map(function(x){ return parseFloat(x.value); }); } }catch(e){}
let dom=null, mcapChg=null;
try{ dom=cg.data.market_cap_percentage.btc; mcapChg=cg.data.market_cap_change_percentage_24h_usd; }catch(e){}
// keep legacy single-symbol fields (BTC) so old consumers don't break
return [{ json: { ticker: ticker, funding: funding, fear_greed: fngNow, fear_greed_7d: fng7,
  btc_dominance: dom, mcap_chg24: mcapChg, features: feats['BTCUSDT'],
  features_multi: feats, funds_multi: funds } }];

// Validate Gates v2 — now runs AFTER Backtest Engine (was: before Fetch 1D, where the
// real backtest did not exist yet and backtest_est.trades was always 0 → gates dead).
// Gates the REAL multi-instance replay: sample size, expectancy, profit factor, TP hit
// rates, and signal confidence (backtest-expert methodology: minimum 30 trades; the
// replay already prices in friction — 5bps fees/side + 2bps slip, stop-first intrabar).
// Output = full passthrough + gate_check. The new "Gates Pass?" IF node blocks
// non-passers (TRUE → Ledger Insert, FALSE → Log NO_TRADE gate-failed reason).
const o = ($input.all()[0] && $input.all()[0].json) || {};
const b = o.backtest || {};
const s = o.signal_echo || o.signal || {};
const fails = [];
if ((b.trades||0) < 30) fails.push("trades<30");
if (!((b.expectancy_R||0) > 0.15)) fails.push("expectancy<=0.15R");
if (!((b.profit_factor||0) >= 1.4)) fails.push("PF<1.4");
if (!((b.tp1_hit_rate||0) >= 0.55)) fails.push("TP1<0.55");
if (!((b.tp2_hit_rate||0) >= 0.35)) fails.push("TP2<0.35");
if (!((s.confidence_0_100||0) >= 75)) fails.push("conf<75");
return [{ json: Object.assign({}, o, { gate_check: { passed: fails.length===0, failed_gates: fails }, validated_at: new Date().toISOString() }) }];

// Log NO_TRADE v3 — two input shapes:
// 1) Quant output passthrough (Is TRADE? FALSE branch): {output, quant_meta}.
// 2) Gate-failed item (Gates Pass? FALSE branch): {backtest, signal_echo, gate_check, ...}.
const q = $input.first().json;
if(q.gate_check){
  const b = q.backtest || {};
  const btStr = 'bt: trades=' + (b.trades||0) + ' exp=' + (b.expectancy_R===null?'-':b.expectancy_R) + 'R pf=' + (b.profit_factor===null?'-':b.profit_factor);
  return [{ json: { decision: 'NO_TRADE', reason: 'gate-failed: ' + (q.gate_check.failed_gates||[]).join(', ') + ' | ' + btStr, at: new Date().toISOString(),
    signal: q.signal_echo || {}, regime: q.regime_echo || null, confluences: [], quant_meta: null } }];
}
const o = q.output || q;
return [{ json: { decision: 'NO_TRADE', reason: o.no_trade_reason || 'filtered', at: new Date().toISOString(),
  signal: o.signal || {}, regime: o.regime || null, confluences: o.confluences || [], quant_meta: q.quant_meta || null } }];

// Backtest Engine v3 — deterministic MULTI-INSTANCE replay (no look-ahead).
// v2 bug (fixed): the single live signal's levels — built from TODAY's 4H ATR and
// 20-bar extremes — were replayed over 400 PAST daily candles. Today's zones almost
// never touched historical prices, so the "backtest" usually returned 0 trades and
// the numbers it did produce were anachronistic (look-ahead bias).
// v3: at every historical bar, recompute the same setup (setup_family + direction)
// using ONLY data up to that bar (SMA20/50, RSI14, ATR14, ADX14, 20-bar H/L — same
// formulas as Compute Indicators), enter at that bar's close, then resolve forward
// bar-by-bar: stop checked first (conservative), TP1/2/3 at 1.5/2.5/4R of that
// instance's own risk, time-stop after TIME_STOP_BARS bars at the bar close.
// Fees 5bps/side + 2bps slip kept; one trade open at a time (sequential, no overlap).
// Signal/context now echo from Quant Engine — Validate Gates has MOVED to after this
// node (Gates Pass? IF blocks non-passers), so the old $('Validate Gates') read is gone.
// Output shape unchanged: {backtest, backtest_trades, backtest_meta, signal_echo,
// regime_echo, confluence_passed, regime_score, decision_echo}.
const q = $('Quant Engine').first().json;
const K = $input.all().map(function(i){ return i.json; }).filter(function(x){ return Array.isArray(x); });
const OUT = (q.output || {});
const S = OUT.signal || {};
const dir = S.direction || 'LONG';
const fam = S.setup_family || 'TREND_CONTINUATION';
const FEE = 0.0005, SLIP = 0.0002, TIME_STOP_BARS = 10, WARM = 60;

function fnum(x){ const v = parseFloat(x); return isNaN(v) ? null : v; }
const H = K.map(function(r){ return fnum(r[2]); });
const L = K.map(function(r){ return fnum(r[3]); });
const C = K.map(function(r){ return fnum(r[4]); });
function smaAt(a, i, n){ if(i+1 < n) return null; let s=0; for(let j=i-n+1;j<=i;j++) s+=a[j]; return s/n; }
function rsiAt(i, n){ if(i < n) return null; let g=0,l=0; for(let j=i-n+1;j<=i;j++){ const d=C[j]-C[j-1]; if(d>0) g+=d; else l-=d; } if(l===0) return 100; return 100-100/(1+(g/n)/(l/n)); }
function atrAt(i, n){ if(i < n) return null; let s=0; for(let j=i-n+1;j<=i;j++){ s+=Math.max(H[j]-L[j], Math.abs(H[j]-C[j-1]), Math.abs(L[j]-C[j-1])); } return s/n; }
function adxAt(i, n){ if(i < n*2+1) return null; let plus=0,minus=0,tr=0; for(let j=i-n*2+1;j<=i;j++){ const up=H[j]-H[j-1], dn=L[j-1]-L[j]; tr+=Math.max(H[j]-L[j], Math.abs(H[j]-C[j-1]), Math.abs(L[j]-C[j-1])); if(up>dn&&up>0) plus+=up; if(dn>up&&dn>0) minus+=dn; } const dip=tr>0?100*plus/tr:0, dim=tr>0?100*minus/tr:0; const sum=dip+dim; return sum>0?100*Math.abs(dip-dim)/sum:0; }
function hiLoAt(i, n){ if(i+1 < n) return [null,null]; let hh=null, ll=null; for(let j=i-n+1;j<=i;j++){ if(hh===null||H[j]>hh) hh=H[j]; if(ll===null||L[j]<ll) ll=L[j]; } return [hh,ll]; }
function R_mult(entry, exit, stop, d){ const risk = d==='LONG' ? entry-stop : stop-entry; if(!(risk>0)) return null; const pnl = d==='LONG' ? exit-entry : entry-exit; return pnl/risk; }

const trades = [];
if(K.length >= WARM+30 && S.entry_zone && (!OUT.decision || OUT.decision === 'TRADE')){
  let open = null; // {i, entry(exec), stop, tps[3], tp_hit[3]}
  for(let i = WARM; i < K.length; i++){
    if(open){
      if(L[i]===null || H[i]===null) continue; // data hole: trade stays open
      const stopHit = dir==='LONG' ? (L[i] <= open.stop) : (H[i] >= open.stop);
      if(stopHit){
        const x = open.stop * (1 - (dir==='LONG' ? FEE+SLIP : -(FEE+SLIP)));
        trades.push({entry_idx: open.i, exit_idx: i, exit:'STOP', R: R_mult(open.entry, x, open.stop, dir), tp_hit: open.tp_hit});
        open = null;
      } else {
        const px = [open.tps[0], open.tps[1], open.tps[2]].map(function(t){ return t===null ? null : (dir==='LONG' ? (H[i] >= t) : (L[i] <= t)); });
        const hit = px.findIndex(function(v){ return v; });
        if(hit !== -1){
          const tval = open.tps[hit];
          const x = tval * (1 - (dir==='LONG' ? FEE : -FEE));
          open.tp_hit = px.map(function(v){ return !!v; });
          trades.push({entry_idx: open.i, exit_idx: i, exit:'TP'+(hit+1), R: R_mult(open.entry, x, open.stop, dir), tp_hit: open.tp_hit});
          open = null;
        } else if(i - open.i >= TIME_STOP_BARS){
          const x = C[i] * (1 - (dir==='LONG' ? FEE+SLIP : -(FEE+SLIP)));
          trades.push({entry_idx: open.i, exit_idx: i, exit:'TIME', R: R_mult(open.entry, x, open.stop, dir), tp_hit: open.tp_hit});
          open = null;
        }
      }
      continue; // resolution bar never triggers a new entry (sequential, matches v2)
    }
    // --- setup trigger at bar i, using only data <= i ---
    const c = C[i]; if(c===null) continue;
    const sma20 = smaAt(C,i,20), sma50 = smaAt(C,i,50);
    const rsi = rsiAt(i,14), atr = atrAt(i,14), adx = adxAt(i,14);
    if(sma20===null || sma50===null || rsi===null || atr===null || atr<=0) continue;
    const up = c>sma20 && sma20>sma50, dn = c<sma20 && sma20<sma50;
    let trig = false;
    if(fam === 'TREND_CONTINUATION'){
      trig = (rsi>40 && rsi<60) && (adx!==null && adx>=20) && (dir==='LONG' ? up : dn);
    } else { // RANGE_FADE
      const hl = hiLoAt(i,20);
      const inRange = (hl[0]!==null) && c>=hl[1] && c<=hl[0];
      trig = (adx!==null && adx<20) && inRange && (dir==='LONG' ? (!up && !dn && rsi<35) : (!up && !dn && rsi>65));
    }
    if(!trig) continue;
    const hl = hiLoAt(i,20); if(hl[0]===null) continue;
    let entry, stop;
    if(dir==='LONG'){
      entry = fam==='TREND_CONTINUATION' ? Math.min(c, sma20) : c;
      stop  = fam==='TREND_CONTINUATION' ? Math.min(hl[1], entry-atr) - atr*0.25 : hl[1] - atr*0.25;
    } else {
      entry = fam==='TREND_CONTINUATION' ? Math.max(c, sma20) : c;
      stop  = fam==='TREND_CONTINUATION' ? Math.max(hl[0], entry+atr) + atr*0.25 : hl[0] + atr*0.25;
    }
    const R = Math.abs(entry - stop); if(!(R>0)) continue;
    const entryExec = dir==='LONG' ? entry*(1+SLIP) : entry*(1-SLIP);
    const Rk = function(m){ return dir==='LONG' ? entry + R*m : entry - R*m; };
    open = { i: i, entry: entryExec, stop: stop, tps: [Rk(1.5), Rk(2.5), Rk(4)], tp_hit: [false,false,false] };
  }
}
function stats(rawTr){
  const tr = rawTr.filter(function(t){ return t.R !== null; });
  const n = tr.length;
  if(!n) return {trades:0,win_rate:0,avg_R:0,expectancy_R:0,profit_factor:0,sharpe:0,max_drawdown_pct:0,tp1_hit_rate:0,tp2_hit_rate:0,tp3_hit_rate:0,notes:'no-sampled-trades'};
  const Rs = tr.map(function(t){ return t.R; });
  let sum = 0, wins = 0, gp = 0, gl = 0;
  for(const r of Rs){ sum += r; if(r > 0){ wins++; gp += r; } else gl -= r; }
  const mean = sum / n;
  let sd = 0; for(const r of Rs) sd += (r-mean)*(r-mean); sd = Math.sqrt(sd/n) || 1e-9;
  let peak = 0, eq = 0, mdd = 0;
  for(const r of Rs){ eq += r; if(eq > peak) peak = eq; const dd = peak - eq; if(dd > mdd) mdd = dd; }
  const buckets = {};
  for(const t of tr){ const m = Math.floor(t.exit_idx/30); buckets[m] = (buckets[m]||0) + t.R; }
  let tot = sum, worst_share = 0;
  for(const k in buckets){ const s = tot !== 0 ? Math.abs(buckets[k]/tot) : 0; if(s > worst_share) worst_share = s; }
  return {
    trades: n,
    win_rate: Math.round(wins/n*1000)/1000,
    avg_R: Math.round(mean*1000)/1000,
    expectancy_R: Math.round(mean*1000)/1000,
    profit_factor: gl > 0 ? Math.round(gp/gl*100)/100 : 999,
    sharpe: Math.round(mean/sd*Math.sqrt(n)*100)/100,
    max_drawdown_pct: Math.round(mdd*100)/100,
    tp1_hit_rate: Math.round(tr.filter(function(t){return t.tp_hit[0];}).length/n*1000)/1000,
    tp2_hit_rate: Math.round(tr.filter(function(t){return t.tp_hit[1];}).length/n*1000)/1000,
    tp3_hit_rate: Math.round(tr.filter(function(t){return t.tp_hit[2];}).length/n*1000)/1000,
    worst_month_pnl_share: Math.round(worst_share*1000)/1000,
    fees_bps_per_side: 5,
    notes: 'deterministic-replay|stop-first-intrabar|fees5bps+slip2bps|1d-multi-instance|no-lookahead|time-stop-'+TIME_STOP_BARS+'bars'
  };
}
const bt = stats(trades);
return [{ json: { backtest: bt, backtest_trades: trades.slice(-60),
  backtest_meta: { candles: K.length, symbol: S.symbol || 'BTCUSDT', engine: 'v3-multi-instance-1d', time_stop_bars: TIME_STOP_BARS, fees_bps_per_side: 5, slip_bps: 2, note: 'no-lookahead: per-instance levels from data<=entry-bar' },
  signal_echo: S, regime_echo: OUT.regime || null,
  confluence_passed: q.confluence_passed || 0, regime_score: q.regime_score || 0,
  decision_echo: 'TRADE' } }];

// Build Telegram Payload v3 (FA) — same inputs, Persian message, single-line safe.
// Reads signal context from Validate Gates (TRADE branch) with fallback to Parse LLM JSON,
// backtest-real from $input (Backtest Engine output on TRADE branch).
let vg = null;
try { vg = $('Validate Gates').first().json; } catch(e) {}
let llm = null;
try { llm = $('Parse LLM JSON').first().json; } catch(e) {}
const cur = $input.first().json;
const o = (vg && (vg.output || vg.decision)) ? (vg.output ? vg : { output: vg }) : (llm && llm.output ? llm : { output: cur.output || cur });
const out = o.output || o;
const s = out.signal || {};
const bReal = cur.backtest || null;
const bEst = out.backtest || {};
function n(x, d){ return (x === null || x === undefined || x === '') ? d : x; }
function faDir(d){ if(d === 'LONG') return 'خرید (لانگ)'; if(d === 'SHORT') return 'فروش (شورت)'; return '—'; }
const decision = out.decision || cur.decision || 'UNKNOWN';
const L = [];
if(decision === 'TRADE'){
  L.push('✅ سیگنال کریپتو — معامله');
  L.push('ارز: ' + (s.symbol || '؟') + ' | جهت: ' + faDir(s.direction));
  if(s.setup_family) L.push('ستاپ: ' + (s.setup_family === 'TREND_CONTINUATION' ? 'ادامه روند' : (s.setup_family === 'RANGE_FADE' ? 'برگشت از سقف/کف رنج' : s.setup_family)));
  L.push('اطمینان: ' + n(s.confidence_0_100, 0) + ' از ۱۰۰');
  L.push('ورود: ' + JSON.stringify(s.entry_zone || []) + ' | حد ضرر: ' + n(s.stop_loss, '؟'));
  L.push('تارگت‌ها: ' + n(s.tp1,'؟') + ' / ' + n(s.tp2,'؟') + ' / ' + n(s.tp3,'؟'));
} else {
  L.push('⛔ بدون معامله');
  L.push('دلیل: ' + (out.no_trade_reason || cur.reason || 'شرایط لازم برقرار نبود'));
}
if(bReal && bReal.trades){
